        for _k in list(_b.keys()):
            _x = _b.get(_k)
            if _k not in ['date', 'time'] and (_x is None or str(_x).strip().lower() in ('', 'none', 'null') or '{' in str(_x)):
                _b.pop(_k, None)
        for _f, _v, _drop in []:
            if str(_b.get(_f)) == str(_v):
                for _k in _drop:
                    _b.pop(_k, None)
        _kind = dict([]).get(str(_b.get('')))
        if _kind == 'date' and '' in _b:
            _b[''] = _date(_b[''])
        if _kind == 'digits' and '' in _b:
            _b[''] = _digits(_b[''])
        for _k in ['date']:
            if isinstance(_b.get(_k), str):
                _b[_k] = _date(_b[_k])
        for _k in ['time']:
            if isinstance(_b.get(_k), str):
                _b[_k] = _time(_b[_k])
        for _k in []:
            if isinstance(_b.get(_k), str):
                try:
                    _b[_k] = float(_b[_k].replace(',', ''))
                except Exception:
                    pass
        _ids = [x for x in str(vars.get('product_ids') or '').split(',') if x]
        if 'product_id' in _b and len(_ids) == 1:
            _b['product_id'] = _ids[0]
        if 'product_id' in _b:
            vars['last_product'] = str(_b.get('product_id'))
except Exception:
